package com.onlinelearning.controller;
import com.onlinelearning.model.*; import com.onlinelearning.repository.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import org.springframework.http.HttpStatus; import org.springframework.web.server.ResponseStatusException; import java.util.List;
@RestController @RequestMapping("/api") public class LessonController {private final LessonRepository lessons;private final CourseRepository courses;public LessonController(LessonRepository l,CourseRepository c){lessons=l;courses=c;} public record Request(String title,String content,int lessonOrder){} @GetMapping("/courses/{courseId}/lessons") public List<Lesson> all(@PathVariable Long courseId){return lessons.findByCourseIdOrderByLessonOrderAsc(courseId);} @PostMapping("/courses/{courseId}/lessons") @PreAuthorize("hasAnyRole('INSTRUCTOR','ADMIN')") public Lesson create(@PathVariable Long courseId,@RequestBody Request r){Course c=courses.findById(courseId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Course not found"));return lessons.save(new Lesson(r.title(),r.content(),r.lessonOrder(),c));}}